          // ceiling — environment management must never run for tens of minutes.
          const budgetMs = Math.min(Number(args.timeoutMs) > 0 ? Number(args.timeoutMs) : DEFAULT_INSTALL_TIMEOUT_MS, MAX_TOOL_TIMEOUT_MS)

          const specs = []
