      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-python-env\",\n  \"version\": \"0.1.2\",\n  \"description\": \"DeepSeek Harness plugin: workspace-scoped Python virtual environment management for agents (pyenv_discover / pyenv_create / pyenv_install / pyenv_uninstall / pyenv_remove). Runs the standard library python -m venv / pip through the host subprocess channel instead of the sandboxed shell, so venv creation, pip bootstrapping, and package-index network access work on Windows/macOS/Linux. Every mutation stays inside the session workspace, the global Python environment is never touched, network failures fall back across PyPI mirrors and common local proxy ports, and no third-party environment manager (uv, virtualenv, ...) is required.\",\n  \"keywords\": [\n    \"dsh-plugin\",\n    \"dsh\",\n    \"deepseek-harness\",\n    \"python\",\n    \"venv\",\n    \"virtualenv\",\n    \"pip\",\n    \"workspace\",\n    \"cross-platform\"\n  ],\n  \"license\": \"MIT\",\n  \"author\": \"Yutong Zou <yutong.zou.24@alumni.ucl.ac.uk> (https://github.com/AngelosZou)\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": {\n      \"default\": \"./lib/index.js\"\n    },\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"docs\",\n    \"CHANGELOG.md\",\n    \"CONTRIBUTING.md\",\n    \"SECURITY.md\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"engines\": {\n    \"node\": \">=20\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"scripts\": {\n    \"test\": \"node --test --test-isolation=none \\\"test/*.test.js\\\"\",\n    \"prepublishOnly\": \"npm test\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/AngelosZou/dsh-python-env.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/AngelosZou/dsh-python-env/issues\"\n  },\n  \"homepage\": \"https://github.com/AngelosZou/dsh-python-env#readme\"\n}\n"
