    {
      "path": "lib/index.js",
      "content": "/**\n * dsh-python-env — host half.\n *\n * Workspace-scoped Python virtual environment management for agents, built\n * around one core insight: the DSH shell sandbox blocks pip's temporary\n * directories and package-index network access, while plugin code runs in\n * the host process. This plugin therefore executes python/pip/venv through\n * the platform subprocess service (the graphlint channel) and compensates\n * for the unrestricted token with strict workspace confinement:\n *\n * 1. Five model-facing tools:\n *    - pyenv_discover — find environments (pyvenv.cfg marker or conventional\n *      names) up to two levels deep and report interpreter/version/pip.\n *    - pyenv_create — standard-library `python -m venv`, verified base\n *      interpreter, idempotent on existing environments.\n *    - pyenv_install — resolve target (explicit / discovered / auto-created\n *      .venv), repair pip via ensurepip, run pip through the mirror/proxy\n *      fallback chain; upgrade flag and workspace-confined editable installs;\n *      foreground or background via ctx.jobs.\n *    - pyenv_uninstall — remove packages from a workspace environment\n *      (`pip uninstall`, offline; never auto-creates an environment).\n *    - pyenv_remove — delete a real environment only.\n * 2. Every model-influenced path resolves through guardWorkspacePath and\n *    must stay inside the session workspace (case-insensitively on Windows).\n *    All plugin state lives under <workspace>/.dsh-pyenv (pip cache, tmp);\n *    children get TMP/TEMP/TMPDIR + PIP_CACHE_DIR re-pointed there, so the\n *    global Python environment, host pip cache, and system temp are never\n *    touched. Commands are argv arrays — no shell interpolation anywhere.\n * 3. Standard library only: no uv/virtualenv dependency. Cross-platform\n *    layouts (Scripts vs bin), interpreter chains (python/py -3 vs\n *    python3/python), and mirror fallback (default -> TUNA -> Aliyun ->\n *    USTC, plus one common-local-proxy-port probe) are built in.\n * 4. Session policy parity: the mutating tools consult the session's\n *    standing sandbox policy and refuse to run in read-only sessions —\n *    host-side execution must not outrank the granted mode.\n * 5. One skill (python-env) and one system-prompt guidance section teach\n *    the agent to use the tools instead of shell pip.\n * 6. Concurrency: mutating tools declare isConcurrencySafe false, so the\n *    tool scheduler serializes them natively; discovery is read-only.\n * 7. Optional, zero-dependency compatibility with dsh-multi-folder: each\n *    tool silently probes ctx.get('multiFolder') at call time (never\n *    declared in inject). Absent, the plugin behaves exactly as if\n *    multi-folder did not exist; present, the user-configured secondary\n *    working directories join the primary workspace as allowed roots.\n */\nimport { registerSkill } from './skill.js'\nimport { registerGuidance } from './guidance.js'\nimport { registerDiscoverTool } from './tools/discover.js'\nimport { registerCreateTool } from './tools/create.js'\nimport { registerInstallTool } from './tools/install.js'\nimport { registerUninstallTool } from './tools/uninstall.js'\nimport { registerRemoveTool } from './tools/remove.js'\n\nexport const name = 'dsh-python-env'\nexport const inject = ['tools', 'skills', 'subprocess', 'jobs', 'sandboxPolicy', 'systemPrompt']\n\nexport function apply(ctx) {\n  registerSkill(ctx)\n  registerGuidance(ctx)\n  registerDiscoverTool(ctx)\n  registerCreateTool(ctx)\n  registerInstallTool(ctx)\n  registerUninstallTool(ctx)\n  registerRemoveTool(ctx)\n}\n"
    },
    {
      "path": "lib/guard.js",
      "content": "/**\n * Workspace confinement: the compensating control for host-side execution.\n * Every tool path the model can influence is resolved here and must land\n * inside the session working directory (case-insensitively on Windows).\n * @module dsh-python-env/guard\n */\nimport { isAbsolute, relative, resolve, sep } from 'node:path'\n\n/**\n * Absolute working directory the executing session was created in.\n * Falls back to process.cwd() for executors without an agent chain.\n */\nexport function sessionCwd(exec) {\n  const header = exec && exec.agent && exec.agent.session && exec.agent.session.header\n  if (header && typeof header.cwd === 'string' && header.cwd.length > 0) return header.cwd\n  return process.cwd()\n}\n\n/** True when `target` equals `root` or lies inside it (case-insensitive on Windows). */\nexport function isWithin(root, target, platform = process.platform) {\n  const rel = relative(root, target)\n  if (rel === '') return true\n  const normalized = platform === 'win32' ? rel.toLowerCase() : rel\n  return normalized !== '..' && !normalized.startsWith('..' + sep) && !isAbsolute(normalized)\n}\n\n/** Raised when a requested path escapes the session working directory. */\nexport class OutsideWorkspaceError extends Error {\n  constructor(requested, sessionRoot, label) {\n    super(\n      (label !== undefined ? label + ' must stay inside the session working directory' : 'the requested path must stay inside the session working directory') +\n        ' (' + sessionRoot + '); got ' + requested + '.',\n    )\n    this.name = 'OutsideWorkspaceError'\n    this.requested = requested\n    this.sessionRoot = sessionRoot\n  }\n}\n\n/**\n * Resolve a model-supplied path against the session workspace and refuse\n * anything outside it. Relative paths resolve against the workspace itself;\n * `undefined`/empty falls back to the workspace.\n */\nexport function guardWorkspacePath(requested, sessionRoot, label) {\n  const root = resolve(sessionRoot)\n  const target = resolve(root, requested === undefined || String(requested).trim().length === 0 ? root : requested)\n  if (isWithin(root, target)) return target\n  throw new OutsideWorkspaceError(target, root, label)\n}\n\n/**\n * Multi-root guard: the primary workspace plus optional extra roots\n * (e.g. dsh-multi-folder secondary working directories). Relative paths\n * still resolve against the primary workspace; an absolute target is\n * accepted when it lands inside ANY allowed root. With no extra roots this\n * is exactly guardWorkspacePath.\n */\nexport function guardAllowedPath(requested, sessionRoot, extraRoots, label) {\n  const primary = resolve(sessionRoot)\n  const target = resolve(primary, requested === undefined || String(requested).trim().length === 0 ? primary : requested)\n  const roots = [primary, ...(Array.isArray(extraRoots) ? extraRoots : [])]\n  for (const root of roots) {\n    if (isWithin(resolve(root), target)) return target\n  }\n  throw new OutsideWorkspaceError(target, primary, label)\n}\n"
    },
    {
      "path": "lib/policy.js",
      "content": "/**\n * Session sandbox-mode parity: the mutating tools (create / install /\n * uninstall / remove) consult the session's standing sandbox policy and\n * refuse to run when the session is not allowed to write — exactly the\n * semantics the shipped file and shell tools have. Host-side subprocess\n * execution bypasses the shell sandbox mechanically, so this gate is what\n * keeps the plugin's power aligned with the mode the user granted the\n * session. Fails closed when the policy service is absent.\n * @module dsh-python-env/policy\n */\n\nexport const WRITABLE_MODES = ['workspace-write', 'danger-full-access']\n\n/** The session's standing sandbox mode, or undefined when unmountable. */\nexport function sessionSandboxMode(ctx, exec) {\n  const sandboxPolicy = ctx.get('sandboxPolicy')\n  if (sandboxPolicy === undefined || typeof sandboxPolicy.resolve !== 'function') return undefined\n  const standing = sandboxPolicy.resolve(exec && exec.agent ? { session: exec.agent.session } : {})\n  return standing && typeof standing.mode === 'string' ? String(standing.mode) : undefined\n}\n\n/**\n * Allow only when the session's mode grants workspace writes. Throws\n * otherwise — including when no policy service is mounted (the plugin\n * cannot verify permission, so it must not proceed).\n */\nexport function assertWritableSession(ctx, exec, action) {\n  const mode = sessionSandboxMode(ctx, exec)\n  if (mode === undefined) {\n    throw new Error(\n      \"dsh-python-env: cannot \" + action + ': no sandbox policy service is mounted, so the session\\'s write permission cannot be verified',\n    )\n  }\n  if (!WRITABLE_MODES.includes(mode)) {\n    throw new Error(\n      'dsh-python-env: cannot ' + action + ': the session is in \"' + mode +\n        '\" mode, which forbids workspace mutations. Switch the session to workspace-write or danger-full-access first.',\n    )\n  }\n  return mode\n}\n"
    },
    {
      "path": "lib/tools/install.js",
      "content": "/**\n * `pyenv_install` — install packages into a workspace virtual environment\n * through the host subprocess channel, with the mirror/proxy fallback chain.\n * Supports foreground and background execution.\n * @module dsh-python-env/tools/install\n */\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport { stat } from 'node:fs/promises'\nimport { join } from 'node:path'\nimport { guardAllowedPath, sessionCwd } from '../guard.js'\nimport { isVenvDir } from '../layout.js'\nimport { pickVenvInterpreter, resolveExistingVenv } from '../venv.js'\nimport { resolveBaseInterpreter } from '../python.js'\nimport { assertWritableSession } from '../policy.js'\nimport { secondaryDirs } from '../secondary.js'\nimport { ensureEnvDirs, pythonChildEnv } from '../envdir.js'\nimport { ensurePip, runInstallAttempts } from '../pip.js'\nimport { JobLog, runForeground, armDeadline, startBackgroundJob, stdioSpec } from '../runner.js'\nimport { BACKGROUND_INSTALL_CAP_MS, DEFAULT_INSTALL_TIMEOUT_MS, DEFAULT_VENV_NAME, MAX_PACKAGES, MAX_SPEC_LENGTH, MAX_TOOL_TIMEOUT_MS } from '../constants.js'\nimport { BACKGROUND_BRANCH, ERROR_BRANCH, FOREGROUND_PROPERTIES, renderAbortedReason, renderForegroundText, renderStopReason } from '../render.js'\n\nconst ATTEMPT_SCHEMA = {\n  type: 'object',\n  additionalProperties: false,\n  properties: {\n    index: { type: 'string', required: true },\n    proxy: { required: true, oneOf: [{ type: 'string' }, { type: 'null' }] },\n    exitCode: { required: true, oneOf: [{ type: 'integer' }, { type: 'null' }] },\n  },\n}\n\nconst INSTALL_FOREGROUND_BRANCH = {\n  type: 'object',\n  additionalProperties: false,\n  properties: {\n    ...FOREGROUND_PROPERTIES,\n    tried: { type: 'array', required: true, items: ATTEMPT_SCHEMA },\n    indexUsed: { required: true, oneOf: [{ type: 'string' }, { type: 'null' }] },\n    proxyUsed: { required: true, oneOf: [{ type: 'string' }, { type: 'null' }] },\n  },\n}\n\n/**\n * Validate and normalize install specs, with editable-install confinement:\n * `-e` / `--editable` targets must be LOCAL paths inside the workspace;\n * remote/VCS editable URLs are rejected (install them as plain VCS\n * requirement specs instead). Validated paths are rewritten to their\n * guarded absolute form.\n */\nfunction validateAndNormalizeSpecs(specs, ws, extraRoots) {\n  const out = []\n  for (let i = 0; i < specs.length; i += 1) {\n    const spec = specs[i]\n    if (spec === '-e' || spec === '--editable') {\n      if (i + 1 >= specs.length) throw new Error('editable spec \"' + spec + '\" is missing its project path')\n      out.push(spec, editablePath(specs[i + 1], ws, extraRoots))\n      i += 1\n      continue\n    }\n    const longForm = /^--editable=(.+)$/.exec(spec)\n    if (longForm !== null) {\n      out.push('--editable=' + editablePath(longForm[1], ws, extraRoots))\n      continue\n    }\n    const shortForm = /^-e(.+)$/.exec(spec)\n    if (shortForm !== null) {\n      out.push('-e', editablePath(shortForm[1], ws, extraRoots))\n      continue\n    }\n    out.push(spec)\n  }\n  return out\n}\n\nfunction editablePath(raw, ws, extraRoots) {\n  const text = String(raw).trim()\n  if (text.length === 0) throw new Error('editable install requires a project path')\n  if (/^(git|hg|svn|bzr)\\+/.test(text) || /^https?:\\/\\//i.test(text)) {\n    throw new Error(\n      'editable install from ' + text.slice(0, 40) + ' is not supported: only local editable paths inside the session workspace are allowed (clone the project into the workspace first, or install it as a plain VCS requirement spec)',\n    )\n  }\n  return guardAllowedPath(text, ws, extraRoots, 'editable path')\n}\n\nexport function registerInstallTool(ctx) {\n  ctx.tools.register(\n    defineTool({\n      name: 'pyenv_install',\n      description:\n        'Install Python packages into a workspace virtual environment. Resolves the target environment (explicit venv argument, discovered environments, or auto-created .venv), repairs a missing pip, then runs pip install through the host subprocess channel. ' +\n        'On network failure it automatically retries across PyPI mirrors (TUNA, Aliyun, USTC) and probes common local proxy ports. ' +\n        'Use this instead of pip in a shell — the shell sandbox blocks package-index network access and pip\\'s temporary directories. Accepts package requirement specs and/or a workspace requirements file. Never touches the global Python environment.',\n      parameters: {\n        packages: {\n          type: 'array',\n          items: { type: 'string' },\n          description: 'pip requirement specs to install, e.g. [\"pytest>=8\", \"tree-sitter\"]. At least one package or a requirements file is required.',\n        },\n        requirements: {\n          type: 'string',\n          description: 'Workspace-relative path to a requirements.txt-style file to install from.',\n        },\n        venv: {\n          type: 'string',\n          description:\n            'Target environment: a directory name or workspace path. Defaults to the single discovered environment (preferring .venv) and auto-creates .venv when none exists. Multiple environments require this argument.',\n        },\n        python: {\n          type: 'string',\n          description: 'Base interpreter for the auto-created environment (see pyenv_create).',\n        },\n        upgrade: {\n          type: 'boolean',\n          description: 'Upgrade the requested packages to the newest available versions (pip --upgrade; applies to every requested spec).',\n        },\n        index: {\n          type: 'string',\n          description: 'Pin one package index URL, e.g. https://pypi.tuna.tsinghua.edu.cn/simple (disables the automatic mirror fallback chain).',\n        },\n        proxy: {\n          type: 'string',\n          description:\n            'Explicit HTTP proxy for pip (\"host:port\" or http(s) URL). Defaults to the ambient HTTP_PROXY/HTTPS_PROXY, then to common local proxy ports after a network failure.',\n        },\n        timeoutMs: {\n          type: 'number',\n          description:\n            'Time budget in milliseconds for this call (default 120000, capped at 120000). When the budget elapses the running process tree is terminated and a detailed stop-reason is returned.',\n        },\n        run_in_background: {\n          type: 'boolean',\n          description: 'Run the install as a background job (poll with job_output). The job is capped at the same 2-minute budget; exceeding it terminates pip and reports a detailed stop-reason.',\n        },\n      },\n      output: {\n        schema: { oneOf: [BACKGROUND_BRANCH, INSTALL_FOREGROUND_BRANCH, ERROR_BRANCH] },\n        render(_args, value) {\n          if (value && typeof value.error === 'string') return [{ type: 'text', text: value.error }]\n          if (value && value.kind === 'background') {\n            return [{ type: 'text', text: 'started background job ' + value.jobId + ' (poll with job_output)' }]\n          }\n          let text = renderForegroundText(value)\n          if (Array.isArray(value.tried) && value.tried.length > 0) {\n            if (text.length > 0 && !text.endsWith('\\n')) text += '\\n'\n            text +=\n              'attempts: ' +\n              value.tried\n                .map((attempt) => attempt.index + (attempt.proxy !== null ? ' via ' + attempt.proxy : '') + ' (exit ' + attempt.exitCode + ')')\n                .join(' -> ')\n          }\n          return [{ type: 'text', text }]\n        },\n      },\n      // No definition-level timeoutMs: the tool owns its deadline so a\n      // timeout surfaces as a detailed stop-reason, not the framework's bare\n      // \"tool call timed out\" message.\n      isConcurrencySafe: () => false,\n      async execute(args, exec) {\n        try {\n          const ws = sessionCwd(exec)\n          assertWritableSession(ctx, exec, 'install packages')\n          const extraRoots = await secondaryDirs(ctx, ws)\n          await ensureEnvDirs(ws)\n          const env = pythonChildEnv(ws)\n          const subprocess = ctx.get('subprocess')\n          if (subprocess === undefined) {\n            throw new Error('dsh-python-env: no subprocess service is mounted (cannot install packages)')\n          }\n          // Per-call budget: model override allowed but capped at the 2-minute\n          // ceiling — environment management must never run for tens of minutes.\n          const budgetMs = Math.min(Number(args.timeoutMs) > 0 ? Number(args.timeoutMs) : DEFAULT_INSTALL_TIMEOUT_MS, MAX_TOOL_TIMEOUT_MS)\n\n          const specs = []\n          if (args.packages !== undefined) {\n            if (!Array.isArray(args.packages)) throw new Error('packages must be an array of requirement strings')\n            for (const raw of args.packages) {\n              const spec = typeof raw === 'string' ? raw.trim() : ''\n              if (spec.length === 0) continue\n              if (spec.length > MAX_SPEC_LENGTH) {\n                throw new Error('package spec too long (max ' + MAX_SPEC_LENGTH + '): ' + spec.slice(0, 80) + '...')\n              }\n              specs.push(spec)\n            }\n            if (specs.length > MAX_PACKAGES) throw new Error('too many packages (max ' + MAX_PACKAGES + ')')\n          }\n          let requirementsPath\n          if (args.requirements !== undefined && String(args.requirements).trim().length > 0) {\n            requirementsPath = guardAllowedPath(args.requirements, ws, extraRoots, 'requirements')\n            const info = await stat(requirementsPath)\n            if (!info.isFile()) throw new Error('requirements is not a file: ' + requirementsPath)\n          }\n          if (specs.length === 0 && requirementsPath === undefined) {\n            throw new Error('nothing to install: pass \"packages\" and/or a \"requirements\" file')\n          }\n          const normalizedSpecs = validateAndNormalizeSpecs(specs, ws, extraRoots)\n\n          // Resolve the target environment (shared logic with pyenv_uninstall).\n          let venvDir = await resolveExistingVenv(ws, args.venv, extraRoots)\n          let created = false\n          if (venvDir === null) {\n            venvDir = join(ws, DEFAULT_VENV_NAME)\n            created = true\n          }\n\n          // Plugin-owned deadline covering the whole call: when it fires, the\n          // live subprocess tree is terminated and a detailed stop-reason is\n          // returned instead of the result (or a bare timeout error).\n          let current = null\n          const deadline = armDeadline(budgetMs, () => current)\n          try {\n            if (created) {\n              const base = await resolveBaseInterpreter(subprocess, args.python, ws, process.platform, exec && exec.signal, (handle) => { current = handle })\n              if (deadline.fired()) {\n                return { error: renderStopReason({ tool: 'pyenv_install', operation: 'resolving the base Python interpreter', budgetMs }) }\n              }\n              const createResult = await runForeground(\n                subprocess,\n                { argv: [...base.argv, '-m', 'venv', venvDir], cwd: ws, stdio: stdioSpec(), graceMs: 15_000, env },\n                exec && exec.signal,\n                (handle) => { current = handle },\n              )\n              if (deadline.fired()) {\n                return {\n                  error: renderStopReason({\n                    tool: 'pyenv_install',\n                    operation: 'auto venv creation ' + venvDir,\n                    budgetMs,\n                    stdout: createResult.stdout.text,\n                    stderr: createResult.stderr.text,\n                  }),\n                }\n              }\n              if (createResult.exitCode === null) {\n                return {\n                  error: renderAbortedReason({\n                    tool: 'pyenv_install',\n                    operation: 'auto venv creation ' + venvDir,\n                    stdout: createResult.stdout.text,\n                    stderr: createResult.stderr.text,\n                  }),\n                }\n              }\n              if (createResult.exitCode !== 0) {\n                throw new Error('auto venv creation failed\\n' + (createResult.stderr.text + '\\n' + createResult.stdout.text).slice(-2000))\n              }\n              if (!(await isVenvDir(venvDir))) {\n                throw new Error('auto venv creation reported success but ' + venvDir + ' has no pyvenv.cfg marker')\n              }\n            }\n            const venvPython = await pickVenvInterpreter(venvDir)\n            if (venvPython === null) throw new Error('virtual environment has no usable interpreter: ' + venvDir)\n            await ensurePip(subprocess, venvPython, ws, env, exec && exec.signal, (handle) => { current = handle })\n            if (deadline.fired()) {\n              return { error: renderStopReason({ tool: 'pyenv_install', operation: 'ensuring pip in ' + venvDir, budgetMs }) }\n            }\n\n            const opts = {\n              subprocess,\n              signal: exec && exec.signal,\n              cwd: ws,\n              venvPython,\n              specs: normalizedSpecs,\n              requirementsPath,\n              index: args.index,\n              proxy: args.proxy,\n              upgrade: args.upgrade === true,\n              env,\n              onSpawn: (handle) => { current = handle },\n            }\n\n            if (args.run_in_background === true) {\n              if (deadline.fired()) {\n                return { error: renderStopReason({ tool: 'pyenv_install', operation: 'preparing the background install', budgetMs }) }\n              }\n              if (exec && exec.signal && exec.signal.aborted) throw new Error('tool call aborted')\n              const log = new JobLog()\n              let live = null\n              let capped = false\n              const capTimer = setTimeout(() => {\n                capped = true\n                if (live !== null) live.terminate()\n              }, BACKGROUND_INSTALL_CAP_MS)\n              if (typeof capTimer.unref === 'function') capTimer.unref()\n              const jobId = startBackgroundJob(ctx, exec, 'pyenv-install', 'pip install in ' + venvDir, log, {\n                cancel: () => {\n                  if (live !== null) live.terminate()\n                },\n                done: async () => {\n                  try {\n                    const outcome = await runInstallAttempts({\n                      ...opts,\n                      signal: undefined,\n                      onSpawn: (handle) => {\n                        live = handle\n                      },\n                      onAttempt: (result) => {\n                        log.append(result.stdout.text)\n                        if (result.stderr.text.length > 0) log.append(result.stderr.text)\n                      },\n                      shouldStop: () => capped,\n                    })\n                    if (capped) {\n                      return {\n                        status: 'failed',\n                        detail: renderStopReason({\n                          tool: 'pyenv_install',\n                          operation: 'pip install into ' + venvDir,\n                          budgetMs: BACKGROUND_INSTALL_CAP_MS,\n                          stdout: outcome.result.stdout.text,\n                          stderr: outcome.result.stderr.text,\n                          tried: outcome.tried,\n                        }),\n                      }\n                    }\n                    if (outcome.ok) return { status: 'completed', detail: 'install finished (index: ' + outcome.indexUsed + ')' }\n                    return { status: 'failed', detail: 'install failed (exit ' + outcome.result.exitCode + ', index: ' + outcome.indexUsed + ')' }\n                  } finally {\n                    clearTimeout(capTimer)\n                  }\n                },\n              })\n              return { kind: 'background', jobId }\n            }\n\n            const outcome = await runInstallAttempts({ ...opts, shouldStop: () => deadline.fired() })\n            if (deadline.fired() && !outcome.ok) {\n              return {\n                error: renderStopReason({\n                  tool: 'pyenv_install',\n                  operation: 'pip install into ' + venvDir,\n                  budgetMs,\n                  stdout: outcome.result.stdout.text,\n                  stderr: outcome.result.stderr.text,\n                  tried: outcome.tried,\n                }),\n              }\n            }\n            if (outcome.result.exitCode === null) {\n              return {\n                error: renderAbortedReason({\n                  tool: 'pyenv_install',\n                  operation: 'pip install into ' + venvDir,\n                  stdout: outcome.result.stdout.text,\n                  stderr: outcome.result.stderr.text,\n                  tried: outcome.tried,\n                }),\n              }\n            }\n            return {\n              kind: 'foreground',\n              exitCode: outcome.result.exitCode,\n              timedOut: outcome.result.timedOut,\n              stdout: outcome.result.stdout,\n              stderr: outcome.result.stderr,\n              tried: outcome.tried,\n              indexUsed: outcome.indexUsed,\n              proxyUsed: outcome.proxyUsed,\n            }\n          } finally {\n            deadline.dispose()\n          }\n        } catch (error) {\n          return { error: error instanceof Error ? error.message : String(error) }\n        }\n      },\n      presentCall: (args) => ({\n        card: 'terminal',\n        title: 'pip install' + (args && Array.isArray(args.packages) && args.packages.length > 0 ? ' ' + args.packages.join(' ') : ''),\n      }),\n    }),\n  )\n}\n"
    },
    {
      "path": "lib/tools/remove.js",
      "content": "/**\n * `pyenv_remove` — delete a workspace virtual environment. Refuses to touch\n * anything that is not a real environment (pyvenv.cfg marker required) or\n * anything outside the session workspace.\n * @module dsh-python-env/tools/remove\n */\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport { rm, stat } from 'node:fs/promises'\nimport { basename } from 'node:path'\nimport { sessionCwd } from '../guard.js'\nimport { assertWritableSession } from '../policy.js'\nimport { secondaryDirs } from '../secondary.js'\nimport { isVenvDir } from '../layout.js'\nimport { resolveVenvArg } from '../venv.js'\nimport { DEFAULT_TOOL_TIMEOUT_MS } from '../constants.js'\nimport { ERROR_BRANCH } from '../render.js'\n\nconst RECORD_SCHEMA = {\n  type: 'object',\n  additionalProperties: false,\n  properties: {\n    removed: { type: 'boolean', required: true },\n    name: { type: 'string', required: true },\n    path: { type: 'string', required: true },\n  },\n}\n\nexport function registerRemoveTool(ctx) {\n  ctx.tools.register(\n    defineTool({\n      name: 'pyenv_remove',\n      description:\n        'Delete a workspace virtual environment. Refuses to delete directories that are not valid virtual environments (the pyvenv.cfg marker is required) or anything outside the session workspace.',\n      parameters: {\n        venv: {\n          type: 'string',\n          required: true,\n          description: 'The environment to delete: a directory name or workspace path (e.g. \".venv\" or \"backend/env\").',\n        },\n      },\n      output: {\n        schema: { oneOf: [ERROR_BRANCH, RECORD_SCHEMA] },\n        render(_args, value) {\n          if (value && typeof value.error === 'string') return [{ type: 'text', text: value.error }]\n          return [{ type: 'text', text: 'removed virtual environment ' + value.path }]\n        },\n      },\n      // Keeps the framework budget: deletion is a single fs op with no\n      // subprocess to terminate, so the plugin-owned deadline does not apply;\n      // the declared 2-minute budget is the backstop.\n      timeoutMs: DEFAULT_TOOL_TIMEOUT_MS,\n      isConcurrencySafe: () => false,\n      async execute(args, exec) {\n        try {\n          const ws = sessionCwd(exec)\n          assertWritableSession(ctx, exec, 'remove a virtual environment')\n          const extraRoots = await secondaryDirs(ctx, ws)\n          if (args.venv === undefined || String(args.venv).trim().length === 0) {\n            throw new Error('venv is required: the environment directory name or path to delete')\n          }\n          const target = resolveVenvArg(args.venv, ws, extraRoots)\n          let exists = false\n          try {\n            exists = (await stat(target)).isDirectory()\n          } catch {\n            // absent — reject below\n          }\n          if (!exists) throw new Error('venv not found: ' + target)\n          if (!(await isVenvDir(target))) {\n            throw new Error('refusing to delete a non-virtual-environment directory (no pyvenv.cfg): ' + target)\n          }\n          await rm(target, { recursive: true, force: true })\n          return { removed: true, name: basename(target), path: target }\n        } catch (error) {\n          return { error: error instanceof Error ? error.message : String(error) }\n        }\n      },\n      presentCall: (args) => ({ card: 'generic', title: 'pyenv_remove ' + String(args && args.venv ? args.venv : '') }),\n    }),\n  )\n}\n"
    },
    {
      "path": "lib/pip.js",
      "content": "/**\n * pip execution: argv construction, pip bootstrap repair, network-failure\n * classification, and the mirror/proxy fallback chain.\n *\n * The chain runs pip against the default index first; a failure classified\n * as NETWORK-level (connection reset/timeout/DNS/unreachable) moves on to\n * the TUNA, Aliyun, and USTC mirrors. After the first network-classified\n * failure with no proxy configured, common local proxy ports on 127.0.0.1\n * are probed once — a live one is retried against the same index. Package\n * resolution errors (e.g. \"No matching distribution found\") are never\n * retried: they are real answers, not network problems.\n * @module dsh-python-env/pip\n */\nimport net from 'node:net'\nimport {\n  DEFAULT_INDEXES,\n  PIP_RETRIES,\n  PIP_SOCKET_TIMEOUT,\n  PROXY_PROBE_PORTS,\n  PROXY_PROBE_TIMEOUT_MS,\n} from './constants.js'\nimport { runForeground, stdioSpec } from './runner.js'\n\nconst NETWORK_MARKERS = [\n  /connection\\s+(?:reset|aborted|refused|failed)/i,\n  /failed to establish a new connection/i,\n  /getaddrinfo|name or service not known|nodename nor servname/i,\n  /(?:connect|read)\\s*timed?\\s*out/i,\n  /timed out/i,\n  /network is unreachable/i,\n  /no route to host/i,\n  /proxyerror/i,\n  /retrying \\(retry\\(total=/i,\n  /could not fetch url/i,\n]\n\n/**\n * Whether pip's stderr describes a network-level failure worth retrying on\n * another index or through a proxy. Resolution failures and TLS errors are\n * deliberately excluded.\n */\nexport function classifyNetworkFailure(stderrText) {\n  const text = String(stderrText ?? '')\n  if (\n    text.includes('No matching distribution found') ||\n    text.includes('ERROR: Could not find a version') ||\n    text.includes('ERROR: No matching distribution')\n  ) {\n    return false\n  }\n  return NETWORK_MARKERS.some((marker) => marker.test(text))\n}\n\n/** Accept \"host:port\" and URLs; anything without a scheme gets http://. */\nexport function normalizeProxyUrl(raw) {\n  const text = String(raw ?? '').trim()\n  if (text.length === 0) return undefined\n  return /^https?:\\/\\//i.test(text) ? text : 'http://' + text\n}\n\n/** An explicit index override must be a real http(s) URL. */\nexport function normalizeIndexUrl(raw) {\n  const text = String(raw ?? '').trim()\n  if (text.length === 0) return undefined\n  if (!/^https?:\\/\\//i.test(text)) throw new Error('index must be an http(s) URL, e.g. https://pypi.tuna.tsinghua.edu.cn/simple')\n  return text.replace(/\\/+$/, '')\n}\n\n/** Ambient proxy configured on the HOST process (the plugin's own env). */\nexport function ambientProxyEnv(env = process.env) {\n  return env.HTTPS_PROXY || env.HTTP_PROXY || env.ALL_PROXY || env.https_proxy || env.http_proxy || env.all_proxy\n}\n\nfunction probePort(port, host, timeoutMs) {\n  return new Promise((resolve) => {\n    const socket = net.connect({ host, port })\n    const done = (ok) => {\n      socket.destroy()\n      resolve(ok)\n    }\n    socket.setTimeout(timeoutMs)\n    socket.once('connect', () => done(true))\n    socket.once('timeout', () => done(false))\n    socket.once('error', () => done(false))\n  })\n}\n\n/** Probe the common local proxy ports; the first live listener wins. */\nexport async function probeLocalProxyPorts(\n  ports = PROXY_PROBE_PORTS,\n  host = '127.0.0.1',\n  timeoutMs = PROXY_PROBE_TIMEOUT_MS,\n) {\n  for (const port of ports) {\n    if (await probePort(port, host, timeoutMs)) return port\n  }\n  return null\n}\n\n/** Full `pip install` argv; index/proxy/upgrade are omitted when unset. */\nexport function buildInstallArgv({ venvPython, specs, requirementsPath, indexUrl, proxyUrl, upgrade }) {\n  const argv = [\n    venvPython,\n    '-m',\n    'pip',\n    'install',\n    '--disable-pip-version-check',\n    '--no-color',\n    '--no-input',\n    '--retries',\n    PIP_RETRIES,\n    '--timeout',\n    PIP_SOCKET_TIMEOUT,\n  ]\n  if (upgrade === true) argv.push('--upgrade')\n  if (indexUrl !== undefined && indexUrl !== null) argv.push('--index-url', indexUrl)\n  if (proxyUrl !== undefined && proxyUrl !== null) argv.push('--proxy', proxyUrl)\n  if (requirementsPath !== undefined) argv.push('-r', requirementsPath)\n  for (const spec of specs) argv.push(spec)\n  return argv\n}\n\n/** `pip uninstall` argv: non-interactive, no network needed. */\nexport function buildUninstallArgv(venvPython, specs) {\n  return [venvPython, '-m', 'pip', 'uninstall', '--disable-pip-version-check', '-y', ...specs]\n}\n\n/**\n * Ensure a virtual environment can run pip: probe `python -m pip`, and when\n * it is missing run `python -m ensurepip --upgrade` (offline, bundled\n * wheels) to repair it. Throws with a platform-aware hint when neither works.\n * An optional `onSpawn` callback receives each live handle so a caller's\n * deadline watchdog can terminate it.\n */\nexport async function ensurePip(subprocess, venvPython, cwd, env, signal, onSpawn) {\n  const probe = await runForeground(\n    subprocess,\n    { argv: [venvPython, '-m', 'pip', '--version'], cwd, stdio: stdioSpec(), graceMs: 5_000, env },\n    signal,\n    onSpawn,\n  )\n  if (probe.exitCode === 0) return\n  const boot = await runForeground(\n    subprocess,\n    { argv: [venvPython, '-m', 'ensurepip', '--upgrade'], cwd, stdio: stdioSpec(), graceMs: 30_000, env },\n    signal,\n    onSpawn,\n  )\n  if (boot.exitCode === 0) return\n  const stderr = boot.stderr.text + '\\n' + boot.stdout.text\n  let hint = ''\n  if (/No module named ensurepip|ensurepip is (disabled|not available)/i.test(stderr)) {\n    hint = ' The interpreter cannot bootstrap pip (missing ensurepip; on Debian/Ubuntu install the python3-venv package).'\n  }\n  throw new Error('pip is missing from the virtual environment and could not be bootstrapped.' + hint + '\\n' + stderr.slice(-2000))\n}\n\nfunction shapeAttempt(indexId, proxyUrl, exitCode) {\n  return { index: indexId, proxy: proxyUrl === undefined ? null : proxyUrl, exitCode }\n}\n\n/**\n * Run the install attempts (mirror chain + one local-proxy discovery).\n *\n * Hooks (both optional):\n * - onSpawn(handle) — called after each spawn, so a caller can terminate the\n *   live attempt (background cap timers).\n * - onAttempt(result) — called after each attempt settles with the raw\n *   result, so a caller can stream attempt output.\n * - shouldStop() — consulted between attempts; true ends the chain early\n *   (the last attempt's result is returned as the failure).\n *\n * @returns\n *   { ok: true,  result, tried, indexUsed, proxyUsed } on success, or\n *   { ok: false, result, tried, indexUsed, proxyUsed } with the failing\n *   attempt's raw output after the chain is exhausted or a non-network\n *   failure ends it early.\n */\nexport async function runInstallAttempts({\n  subprocess,\n  signal,\n  cwd,\n  venvPython,\n  specs,\n  requirementsPath,\n  index,\n  proxy,\n  upgrade,\n  env,\n  onSpawn,\n  onAttempt,\n  shouldStop,\n  probeProxy,\n}) {\n  const pinnedIndex = normalizeIndexUrl(index)\n  const explicitProxy = normalizeProxyUrl(proxy)\n  const ambient = explicitProxy === undefined ? ambientProxyEnv() : undefined\n  const attempts = pinnedIndex !== undefined ? [{ id: 'custom-index', indexUrl: pinnedIndex }] : DEFAULT_INDEXES\n  let proxyUrl = explicitProxy !== undefined ? explicitProxy : normalizeProxyUrl(ambient)\n  const probeFn = probeProxy !== undefined ? probeProxy : probeLocalProxyPorts\n  let probedLocal = false\n  const tried = []\n  let last = null\n\n  for (let i = 0; i < attempts.length; i += 1) {\n    if (shouldStop !== undefined && shouldStop()) break\n    const attempt = attempts[i]\n    const argv = buildInstallArgv({ venvPython, specs, requirementsPath, indexUrl: attempt.indexUrl, proxyUrl, upgrade })\n    // Short grace: when a deadline fires, the tree must settle fast so the\n    // tool can return its detailed stop-reason close to the time budget.\n    const spec = { argv, cwd, stdio: stdioSpec(), graceMs: 5_000, env }\n    const result = await runForegroundWith(signal, subprocess, spec, onSpawn)\n    tried.push(shapeAttempt(attempt.id, proxyUrl, result.exitCode))\n    last = { result, argv }\n    if (onAttempt !== undefined) onAttempt(result)\n    if (result.exitCode === 0) {\n      return { ok: true, result, tried, indexUsed: attempt.id, proxyUsed: proxyUrl === undefined ? null : proxyUrl }\n    }\n    if (shouldStop !== undefined && shouldStop()) break\n    if (classifyNetworkFailure(result.stderr.text)) {\n      if (proxyUrl === undefined && !probedLocal) {\n        probedLocal = true\n        const port = await probeFn()\n        if (port !== null && port !== undefined) {\n          proxyUrl = 'http://127.0.0.1:' + port\n          i -= 1 // retry the same index through the discovered proxy\n          continue\n        }\n      }\n      continue // next mirror\n    }\n    break // non-network failure: surface immediately\n  }\n\n  const lastAttempt = tried[tried.length - 1]\n  const failed = last !== null ? last.result : { exitCode: null, timedOut: false, stdout: { text: '', truncated: false }, stderr: { text: '', truncated: false } }\n  return {\n    ok: false,\n    result: failed,\n    tried,\n    indexUsed: lastAttempt === undefined ? null : lastAttempt.index,\n    proxyUsed: proxyUrl === undefined ? null : proxyUrl,\n  }\n}\n\nasync function runForegroundWith(signal, subprocess, spec, onSpawn) {\n  const handle = subprocess.spawn(signal === undefined ? spec : { ...spec, signal })\n  if (onSpawn !== undefined) onSpawn(handle)\n  const outcome = await handle.done\n  return {\n    exitCode: outcome.exitCode === undefined ? null : outcome.exitCode,\n    timedOut: outcome.exitCode === null,\n    stdout: streamShape(handle.collected && handle.collected.stdout),\n    stderr: streamShape(handle.collected && handle.collected.stderr),\n  }\n}\n\nfunction streamShape(reader) {\n  if (reader === undefined || reader === null) return { text: '', truncated: false }\n  const read = reader.readFrom(0)\n  return {\n    text: typeof read.text === 'string' ? read.text : '',\n    truncated: !!read.lossy,\n    ...(read.spillPath !== undefined ? { spillPath: read.spillPath } : {}),\n  }\n}\n"
